  def test_cart(self):
    # Login first to avoid redirection
    self.driver.get("http://localhost:5173/login")
    self.driver.set_window_size(1143, 864)
    time.sleep(1)
    self.driver.find_element(By.NAME, "email").send_keys("customer@branddna.ai")
    self.driver.find_element(By.NAME, "password").send_keys("password123")
    self.driver.find_element(By.CSS_SELECTOR, ".py-4").click()
    time.sleep(2)

    # Go to home page to click product
    self.driver.get("http://localhost:5173/")
    time.sleep(2)
    
    # Click 1st product link using JS to avoid interception
    products = self.driver.find_elements(By.XPATH, "//a[contains(@href, '/customer/product/')]")
    if products:
        self.driver.execute_script("arguments[0].click();", products[0])
    else:
        raise Exception("No products found on home page")
    
    time.sleep(2)
    
    # Add to Shopping Cart
    add_btn = self.driver.find_element(By.XPATH, "//button[contains(., 'Add to Shopping Cart')]")
    self.driver.execute_script("arguments[0].click();", add_btn)
    time.sleep(1)
    
    # Open Cart
    cart_btn = self.driver.find_element(By.XPATH, "//*[contains(text(), 'Cart')]")
    self.driver.execute_script("arguments[0].click();", cart_btn)
    time.sleep(2)
    self.driver.close()
  
